const webhookBody = $('Webhook').item.json.body;
const contextoRows = $('Buscar Contexto de Mapeamento').all().map(item => item.json);
const historicoRows = $('Buscar Historico da Sessao').all().map(item => item.json);

const contextoTexto = JSON.stringify(contextoRows, null, 2);

const systemPrompt = `Voce e o assistente de mapeamento do sistema da Getnet. Seu papel e ajudar usuarios internos a consultar e entender o status de mapeamento de terminais/equipamentos. Responda de forma direta e objetiva, em portugues. Use apenas os dados de contexto fornecidos abaixo - se nao souber algo, diga que nao tem essa informacao em vez de inventar.\n\nContexto de mapeamento disponivel para esta conversa:\n${contextoTexto}`;

const historyMessages = historicoRows.map(row => ({
  role: row.role,
  content: row.content,
}));

const messages = [
  ...historyMessages,
  { role: 'user', content: webhookBody.message },
];

return [{
  json: {
    sessionId: webhookBody.sessionId,
    userId: webhookBody.userId,
    userMessage: webhookBody.message,
    anthropicBody: {
      model: 'claude-sonnet-5',
      max_tokens: 2048,
      system: systemPrompt,
      messages,
    },
  },
}];

const claudeResponse = $input.first().json;
const prev = $('Montar Prompt').item.json;

const replyText = claudeResponse.content && claudeResponse.content[0]
  ? claudeResponse.content[0].text
  : 'Nao consegui gerar uma resposta agora.';

return [{
  json: {
    sessionId: prev.sessionId,
    userId: prev.userId,
    userMessage: prev.userMessage,
    reply: replyText,
  },
}];
